#!/usr/bin/env python3
# code generated by GPT6 to go through all the csv outputs
"""Summarize frame-level detection CSVs using only the Python standard library.

One row must represent one frame. See README.md for formats and metric definitions.
"""

import argparse
import ast
from collections import Counter
import csv
import json
import math
from pathlib import Path
import re
import sys


ALIASES = {
    "boxes": ("boxes", "bboxes", "bbox", "bounding_boxes", "bounding_box", "detection_boxes", "detections", "xyxy"),
    "confidence": ("confidence", "confidences", "confidence_scores", "scores", "conf"),
    "visibility": ("visibility", "visible", "is_visible"),
    "frame": ("frame", "frame_id", "frame_index", "frame_number", "frame_idx"),
}
COUNTS = (
    "total_frames", "frames_with_detection", "frames_without_detection",
    "frames_with_multiple_detections", "frames_with_unknown_box_count",
    "frames_with_unknown_confidence_count", "frames_checked_for_mismatch",
    "frames_with_count_mismatch", "total_boxes", "total_confidences",
    "invalid_boxes", "invalid_confidences", "valid_confidences",
    "low_confidence_detections", "frames_with_low_confidence",
    "frames_with_missing_visibility", "duplicate_frame_rows", "frames_with_issues",
    "summary_rows_skipped",
)


def normalize(value):
    return re.sub(r"[^a-z0-9]", "", value.lower())


def choose_column(headers, role, explicit=None):
    if explicit:
        if explicit not in headers:
            raise ValueError(f"Column {explicit!r} not found. Available: {headers}")
        return explicit
    matches = [h for h in headers if normalize(h) in {normalize(a) for a in ALIASES[role]}]
    if len(matches) > 1:
        raise ValueError(f"Ambiguous {role} columns {matches}; specify --{role}-col")
    if not matches and role in ("boxes", "confidence"):
        raise ValueError(f"Cannot find {role} column in {headers}; specify --{role}-col")
    return matches[0] if matches else None


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def parse_values(text, role, blank_is_empty=False):
    """Return entries; None means count unknown, [] means explicitly zero."""
    if text is None or text.strip().lower() in ("", "null", "none", "nan", "na", "n/a"):
        return [] if blank_is_empty else None
    try:
        value = json.loads(text)
    except (ValueError, TypeError):
        try:
            value = ast.literal_eval(text)
        except (ValueError, SyntaxError, TypeError, RecursionError) as exc:
            raise ValueError("Expected a JSON/Python list; could not parse value") from exc
    if role == "confidence" and isinstance(value, (int, float)) and not isinstance(value, bool):
        return [value]
    if not isinstance(value, (list, tuple)):
        raise ValueError("Expected a list (or a scalar confidence)")
    # A flat four-coordinate list represents one box, not four boxes.
    if role == "boxes" and value and all(not isinstance(v, (list, tuple, dict)) for v in value):
        if len(value) != 4:
            raise ValueError("A flat box must contain exactly four coordinates")
        return [value]
    return list(value)


def valid_box(box, box_format):
    if not isinstance(box, (list, tuple)) or len(box) != 4 or not all(is_number(v) for v in box):
        return False
    a, b, c, d = box
    if box_format == "xyxy":
        return c > a and d > b
    if box_format == "xywh":
        return c > 0 and d > 0
    return True


class Summary:
    def __init__(self):
        self.counts = Counter({key: 0 for key in COUNTS})
        self.visibility = Counter()
        self.histogram = Counter()
        self.conf_sum = 0.0
        self.conf_min = None
        self.conf_max = None

    def merge(self, other):
        self.counts.update(other.counts)
        self.visibility.update(other.visibility)
        self.histogram.update(other.histogram)
        self.conf_sum += other.conf_sum
        if other.conf_min is not None:
            self.conf_min = other.conf_min if self.conf_min is None else min(self.conf_min, other.conf_min)
            self.conf_max = other.conf_max if self.conf_max is None else max(self.conf_max, other.conf_max)

    def as_dict(self):
        c = self.counts
        known_boxes = c["total_frames"] - c["frames_with_unknown_box_count"]
        def ratio(numerator, denominator):
            return numerator / denominator if denominator else None
        return {
            **c,
            "frames_with_known_box_count": known_boxes,
            "detection_rate": ratio(c["frames_with_detection"], known_boxes),
            "multiple_detection_rate": ratio(c["frames_with_multiple_detections"], known_boxes),
            "mismatch_rate": ratio(c["frames_with_count_mismatch"], c["frames_checked_for_mismatch"]),
            "mean_boxes_per_frame": ratio(c["total_boxes"], known_boxes),
            "max_boxes_per_frame": max(self.histogram, default=None),
            "confidence_mean": ratio(self.conf_sum, c["valid_confidences"]),
            "confidence_min": self.conf_min,
            "confidence_max": self.conf_max,
        }


def analyze_file(path, args, issue_writer):
    summary = Summary()
    c = summary.counts
    seen = set()
    with path.open(encoding="utf-8-sig", newline="") as stream:
        reader = csv.DictReader(stream, delimiter=args.delimiter, strict=True)
        headers = reader.fieldnames
        if not headers or len(headers) != len(set(headers)) or any(not h.strip() for h in headers):
            raise ValueError("Missing, empty, or duplicate column headers")
        columns = {role: choose_column(headers, role, getattr(args, role + "_col")) for role in ALIASES}
        # runModel.py writes blank detections and a six-field summary footer.
        exporter_schema = headers == ["frame_number", "visibility", "xyxy", "confidence"]
        blank_is_empty = exporter_schema if args.blank_is_empty is None else args.blank_is_empty
        box_format = "xyxy" if args.box_format == "unspecified" and normalize(columns["boxes"]) == "xyxy" else args.box_format
        if args.sequence_col and args.sequence_col not in headers:
            raise ValueError(f"Sequence column {args.sequence_col!r} not found")
        for row_number, row in enumerate(reader, start=2):
            if (exporter_schema and row.get("frame_number") == "Detection count is"
                    and row.get("xyxy") == "the ratio is"
                    and len(row.get(None, [])) == 2 and row[None][0] == "total frames"):
                c["summary_rows_skipped"] += 1
                continue
            c["total_frames"] += 1
            problems = []
            frame = row.get(columns["frame"], "") if columns["frame"] else ""
            if None in row or any(value is None for value in row.values()):
                problems.append("CSV row has a different field count than the header")
            if columns["frame"]:
                sequence = row.get(args.sequence_col, "") if args.sequence_col else ""
                key = (sequence, frame)
                if not frame or (args.sequence_col and not sequence):
                    problems.append("Missing frame or sequence ID")
                elif key in seen:
                    c["duplicate_frame_rows"] += 1
                    problems.append("Duplicate frame ID within file/sequence; row retained in totals")
                else:
                    seen.add(key)

            parsed = {}
            for role in ("boxes", "confidence"):
                try:
                    parsed[role] = parse_values(row.get(columns[role]), role, blank_is_empty)
                except ValueError as exc:
                    parsed[role] = None
                    problems.append(f"{role}: {exc}")
                if parsed[role] is None:
                    c["frames_with_unknown_box_count" if role == "boxes" else "frames_with_unknown_confidence_count"] += 1
                    problems.append(f"{role}: count unknown")
            boxes, confidences = parsed["boxes"], parsed["confidence"]
            if boxes is not None:
                n = len(boxes)
                c["total_boxes"] += n
                c["frames_with_detection"] += n > 0
                c["frames_without_detection"] += n == 0
                c["frames_with_multiple_detections"] += n > 1
                summary.histogram[n] += 1
                bad = sum(not valid_box(box, box_format) for box in boxes)
                c["invalid_boxes"] += bad
                if bad:
                    problems.append(f"{bad} invalid box entries")
            if confidences is not None:
                c["total_confidences"] += len(confidences)
                good = [v for v in confidences if is_number(v) and 0 <= v <= 1]
                bad = len(confidences) - len(good)
                c["invalid_confidences"] += bad
                c["valid_confidences"] += len(good)
                low = sum(v < args.low_confidence for v in good)
                c["low_confidence_detections"] += low
                c["frames_with_low_confidence"] += low > 0
                summary.conf_sum += sum(good)
                if good:
                    summary.conf_min = min(good) if summary.conf_min is None else min(summary.conf_min, min(good))
                    summary.conf_max = max(good) if summary.conf_max is None else max(summary.conf_max, max(good))
                if bad:
                    problems.append(f"{bad} confidence entries are nonnumeric, nonfinite, or outside [0,1]")
            if boxes is not None and confidences is not None:
                c["frames_checked_for_mismatch"] += 1
                if len(boxes) != len(confidences):
                    c["frames_with_count_mismatch"] += 1
                    problems.append(f"Box/confidence count mismatch: {len(boxes)} vs {len(confidences)}")
            visibility = row.get(columns["visibility"]) if columns["visibility"] else None
            if visibility is None or visibility.strip().lower() in ("", "null", "none", "nan", "na", "n/a"):
                c["frames_with_missing_visibility"] += 1
            else:
                summary.visibility[visibility.strip()] += 1
            if problems:
                c["frames_with_issues"] += 1
                issue_writer.writerow([str(path), row_number, frame, " | ".join(problems)])
    return summary, columns


def write_csv(path, rows, fieldnames):
    with path.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def resolve_input_dir(input_dir):
    """Honor explicit paths; default strictly to output_csv beside this script."""
    if input_dir is not None:
        return Path(input_dir).expanduser().resolve()
    return Path(__file__).resolve().parent / "output_csv"


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input_dir", nargs="?", help="CSV folder; defaults to output_csv beside this script, regardless of cwd")
    parser.add_argument("--output-dir", help="Report folder; defaults to csv_summary beside this script")
    parser.add_argument("--recursive", action="store_true")
    for role in ALIASES:
        parser.add_argument(f"--{role}-col")
    parser.add_argument("--sequence-col", help="Video/sequence ID, used with frame ID for duplicate checks")
    parser.add_argument("--box-format", choices=("unspecified", "xyxy", "xywh"), default="unspecified")
    blanks = parser.add_mutually_exclusive_group()
    blanks.add_argument("--blank-is-empty", dest="blank_is_empty", action="store_true", help="Treat blank/null box/confidence cells as zero entries")
    blanks.add_argument("--blank-is-unknown", dest="blank_is_empty", action="store_false", help="Treat blank/null values as unknown, even for runModel.py exports")
    parser.set_defaults(blank_is_empty=None)
    parser.add_argument("--low-confidence", type=float, default=0.5)
    parser.add_argument("--delimiter", default=",")
    args = parser.parse_args(argv)
    if not 0 <= args.low_confidence <= 1:
        parser.error("--low-confidence must be between 0 and 1")
    if len(args.delimiter) != 1:
        parser.error("--delimiter must be one character")
    try:
        source = resolve_input_dir(args.input_dir)
    except ValueError as exc:
        parser.error(str(exc))
    output = (Path(args.output_dir).expanduser().resolve() if args.output_dir
              else Path(__file__).resolve().parent / "csv_summary")
    if not source.is_dir():
        parser.error(f"Input directory does not exist: {source}\n"
                     "Pass the actual output_csv folder path; quote paths containing spaces.")
    if source == output or output in source.parents:
        parser.error("Output directory must not equal or contain the input directory")
    paths = sorted(p for p in (source.rglob("*") if args.recursive else source.iterdir())
                   if p.is_file() and p.suffix.lower() == ".csv" and output not in p.parents)
    if not paths:
        parser.error(f"No CSV files found in {source}\n"
                     "If the CSV files are in subfolders, add --recursive.")
    output.mkdir(parents=True, exist_ok=True)
    total = Summary()
    file_rows, visibility_rows, histogram_rows, metadata, errors = [], [], [], [], []
    multiple_ball_videos = []
    with (output / "issues.csv").open("w", newline="", encoding="utf-8") as stream:
        writer = csv.writer(stream)
        writer.writerow(["file", "csv_record_number", "frame_id", "issues"])
        for path in paths:
            try:
                stats, columns = analyze_file(path, args, writer)
            except (ValueError, OSError, UnicodeError, csv.Error) as exc:
                errors.append({"file": str(path), "error": str(exc)})
                print(f"ERROR reading {path}: {exc}", file=sys.stderr)
                continue
            total.merge(stats)
            name = str(path.relative_to(source))
            file_rows.append({"file": name, **stats.as_dict()})
            if stats.counts["frames_with_multiple_detections"] > 0:
                multiple_ball_videos.append({
                    "video_id": str(Path(name).with_suffix("")),
                    "csv_file": name,
                    "total_frames": stats.counts["total_frames"],
                    "frames_with_multiple_detections": stats.counts["frames_with_multiple_detections"],
                    "frames_with_detection": stats.counts["frames_with_detection"],
                    "total_boxes": stats.counts["total_boxes"],
                    "max_boxes_per_frame": max(stats.histogram),
                })
            metadata.append({"file": name, "columns": columns})
            for label, count in sorted(stats.visibility.items()):
                visibility_rows.append({"file": name, "visibility": label, "count": count})
            histogram_rows.extend({"file": name, "box_count": n, "frame_count": count}
                                  for n, count in sorted(stats.histogram.items()))
    for label, count in sorted(total.visibility.items()):
        visibility_rows.append({"file": "__ALL_FILES__", "visibility": label, "count": count})
    histogram_rows.extend({"file": "__ALL_FILES__", "box_count": n, "frame_count": count}
                          for n, count in sorted(total.histogram.items()))
    write_csv(output / "per_file_summary.csv", file_rows, ["file", *total.as_dict()])
    write_csv(output / "visibility_counts.csv", visibility_rows, ["file", "visibility", "count"])
    write_csv(output / "detection_histogram.csv", histogram_rows, ["file", "box_count", "frame_count"])
    # One CSV per video. Keep relative paths to distinguish nested directories.
    video_ids = [row["video_id"] for row in multiple_ball_videos]
    write_csv(output / "multiple_ball_videos.csv", multiple_ball_videos,
              ["video_id", "csv_file", "total_frames", "frames_with_multiple_detections",
               "frames_with_detection", "total_boxes", "max_boxes_per_frame"])
    multiple_ball_counts = {
        row["csv_file"]: row["frames_with_multiple_detections"]
        for row in multiple_ball_videos
    }
    multiple_ball_lines = [
        f"{row['csv_file']}: multiple_ball_frames={row['frames_with_multiple_detections']}, "
        f"detected_frames={row['frames_with_detection']}, total_boxes={row['total_boxes']}"
        for row in multiple_ball_videos
    ]
    (output / "multiple_ball_videos.txt").write_text(
        "".join(line + "\n" for line in multiple_ball_lines), encoding="utf-8")
    report = {
        "status": ("partial" if file_rows else "failed") if errors else "complete",
        "files_found": len(paths), "files_processed": len(file_rows), "files_failed": len(errors),
        "input_directory": str(source), "output_directory": str(output),
        "settings": vars(args),
        "multiple_ball_video_count": len(video_ids),
        "videos_with_multiple_detections": video_ids,
        "multiple_ball_frame_counts_by_file": multiple_ball_counts,
        "multiple_ball_video_details": multiple_ball_videos,
        "assumptions": [
            "One CSV row is one frame; duplicate rows remain included. IDs are scoped to file and optional sequence.",
            "Known runModel.py summary footers are excluded and counted as summary_rows_skipped.",
            "For the frame_number,visibility,xyxy,confidence schema, blank detections mean zero unless overridden; xyxy geometry is validated automatically.",
            "Totals exclude files that failed to read. issues.csv may include rows from a failed file before its error.",
            "Detection counts count stored box entries, including invalid entries flagged separately.",
            "Unknown counts are excluded from detection/mismatch rate denominators.",
            "Confidence statistics use only numeric, finite values in [0,1], including unmatched confidence entries.",
            "Visibility is one scalar category per frame; spelling and case are preserved.",
            "Frames omitted from the CSV cannot be counted. No ground-truth accuracy metrics are calculated.",
        ],
        "overall": total.as_dict(), "visibility_counts": dict(total.visibility),
        "detection_histogram": dict(sorted(total.histogram.items())),
        "files": metadata, "errors": errors,
    }
    (output / "summary.json").write_text(json.dumps(report, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    print(json.dumps({"files_processed": len(file_rows), "files_failed": len(errors),
                      **total.as_dict(), "visibility_counts": dict(total.visibility)}, indent=2))
    print(f"Reports saved to: {output}")
    print(f"Videos with multiple detections ({len(video_ids)}); counts are frames or cumulative boxes as labeled")
    for line in multiple_ball_lines:
        print(line)
    if errors:
        if file_rows:
            print("Some files failed; see summary.json for errors. Totals are partial.", file=sys.stderr)
        else:
            print("All files failed. The zero totals are not data results; fix the errors above.", file=sys.stderr)
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
